model.css:
/* Fonts: if Slate blocks this address, the page falls back to Georgia and the system sans-serif. */
@import url("https://fonts.googleapis.com/css2?family=Newsreader:ital,opsz,wght@0,6..72,400..600;1,6..72,400..600&family=Hanken+Grotesk:wght@400..700&display=swap");
.fto2 {
  --page: #ffffff;
  --surface: #ffffff;
  --band: #f1f4f0;
  --ink: #15171a;
  --ink-2: #474c52;
  --muted: #737980;
  --grid: #e4e8e3;
  --track: #eceeea;
  --ring: rgba(21,23,26,0.12);
  --s1: #1d6b52;
  --s1-soft: rgba(29,107,82,0.10);
  --s1-ret: #93c2b1;
  --s2: #c2620c;
  --dim: #c5cbc6;
  --ref: #15171a;
  --up: #a33b2b;
  --down: #1d6b52;
  --focus: #1d6b52;
  --c1: #2a78d6; --c2: #1baf7a; --c3: #eda100; --c4: #e87ba4; --c5: #008300; --c6: #6250d6; --seq: #1d6b52;
  --on0: #15171a; --on1: #ffffff; --on2: #15171a; --on3: #15171a; --on4: #15171a; --on5: #ffffff; --on6: #ffffff;
  --font-ui: "Hanken Grotesk", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --font-data: "Hanken Grotesk", system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  --font-display: "Newsreader", Georgia, "Times New Roman", serif;
}
.fto2 * { box-sizing: border-box; }
.fto2 [hidden] { display: none !important; }
.fto2 { margin: 0; background: var(--page); color: var(--ink); font-family: var(--font-ui); font-size: 15px; line-height: 1.5; }
.fto2 .wrap { max-width: 1240px; margin: 0 auto; padding-inline: 20px; padding-block: 24px 48px; display: grid; grid-template-columns: minmax(0, 1fr); gap: 22px; }
.fto2 header { display: grid; gap: 12px; }
.fto2 .topbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; flex-wrap: wrap; }
.fto2 .asof { font-size: 12.5px; color: var(--muted); font-variant-numeric: tabular-nums; }
.fto2 .topbar .right { display: flex; gap: 14px; align-items: center; }
.fto2 .unit { font-size: 12px; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-2); font-weight: 600; }
.fto2 .titles { display: grid; gap: 4px; }
.fto2 h1 { font-family: var(--font-display); font-weight: 500; font-size: clamp(28px, 4.2vw, 38px); line-height: 1.12; margin: 0; letter-spacing: -0.01em; text-wrap: balance; }
.fto2 h2 { font-weight: 600; font-size: 20px; line-height: 1.2; margin: 0; text-wrap: balance; }
.fto2 h3 { font-weight: 600; font-size: 14.5px; margin: 0; }
.fto2 p { margin: 0; max-width: 78ch; }
.fto2 .period, .fto2 .sub { color: var(--ink-2); }
.fto2 .sub { font-size: 13.5px; }
.fto2 .controls { display: flex; gap: 10px 20px; align-items: center; flex-wrap: wrap; }
.fto2 .ctl { display: inline-flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.fto2 .label { font-size: 13px; color: var(--ink-2); }
.fto2 .seg { display: inline-flex; border: 1px solid var(--ring); border-radius: 6px; overflow: hidden; background: var(--surface); }
.fto2 .seg button { font: inherit; font-size: 13px; padding: 5px 12px; border: 0; background: transparent; color: var(--ink); cursor: pointer; white-space: nowrap; }
.fto2 .seg button + button { border-left: 1px solid var(--ring); }
.fto2 .seg button[aria-pressed="true"], .fto2 .seg button[aria-checked="true"] { background: var(--ink); color: var(--surface); font-weight: 600; }
.fto2 .seg.lang button { padding: 4px 11px; font-size: 12px; letter-spacing: .05em; font-weight: 600; }
.fto2 button:focus-visible, .fto2 input:focus-visible, .fto2 select:focus-visible, .fto2 [role="tab"]:focus-visible, .fto2 summary:focus-visible, .fto2 tr:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
.fto2 select { font: inherit; font-size: 13.5px; padding: 5px 10px; border: 1px solid var(--ring); border-radius: 6px; background: var(--surface); color: var(--ink); }
.fto2 .fbar { display: grid; gap: 6px; border-top: 1px solid var(--grid); border-bottom: 1px solid var(--grid); padding: 10px 0 8px; margin-top: 4px; }
.fto2 .fbar .fb-title { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
.fto2 .fbar .fb { grid-auto-flow: column; align-items: center; gap: 8px; }
.fto2 .fbar .fb > label, .fto2 .fbar .fb > span:first-child { font-size: 11px; letter-spacing: .07em; text-transform: uppercase; color: var(--muted); font-weight: 600; }
.fto2 .fbar .fb-row { gap: 8px 26px; align-items: center; }
.fto2 .fbar .fb-sum { font-size: 12px; color: var(--muted); }
.fto2 .fb-title { font-family: var(--font-ui); font-size: 11.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--ink-2); }
.fto2 .fb-row { display: flex; flex-wrap: wrap; gap: 12px 22px; align-items: end; }
.fto2 .fb { display: grid; gap: 4px; justify-items: start; min-width: 0; }
.fto2 .fb > label, .fto2 .fb > span { font-size: 12px; color: var(--ink-2); font-weight: 600; }
.fto2 .fb select { max-width: 100%; }
.fto2 .fb-dates { display: flex; flex-wrap: wrap; gap: 6px; align-items: center; }
.fto2 input[type="date"] { font: inherit; font-size: 13.5px; padding: 4px 8px; border: 1px solid var(--ring); border-radius: 6px; background: var(--surface); color: var(--ink); font-variant-numeric: tabular-nums; }
.fto2 .switch { display: inline-flex; align-items: center; gap: 8px; font: inherit; font-size: 13.5px; color: var(--ink); background: none; border: 0; padding: 4px 0; cursor: pointer; }
.fto2 .switch i { position: relative; width: 34px; height: 20px; border-radius: 10px; background: var(--dim); flex: none; }
.fto2 .switch i::after { content: ""; position: absolute; top: 2px; left: 2px; width: 16px; height: 16px; border-radius: 50%; background: var(--surface); }
.fto2 .switch[aria-checked="true"] i { background: var(--s1); }
.fto2 .switch[aria-checked="true"] i::after { left: 16px; }
.fto2 .switch b { font-weight: 600; min-width: 2.2em; }
.fto2 .switch:disabled { opacity: .45; cursor: default; }
.fto2 .fb-pick { display: inline-flex; align-items: center; gap: 8px; font-size: 13px; background: var(--surface); border: 1px solid var(--s1); color: var(--ink); border-radius: 999px; padding: 4px 6px 4px 12px; }
.fto2 .fb-pick[hidden] { display: none; }
.fto2 .fb-pick button { font: inherit; border: 0; background: var(--track); border-radius: 999px; width: 22px; height: 22px; cursor: pointer; color: var(--ink); line-height: 1; }
.fto2 [data-pick] { cursor: pointer; }
.fto2 svg [data-pick]:hover { opacity: .78; }
.fto2 td.pickc { text-decoration: underline dotted var(--muted); text-underline-offset: 3px; }
.fto2 td.pickc:hover, .fto2 td.nc[data-pick]:hover { color: var(--s1); }
.fto2 .fb-reset { font: inherit; font-size: 13px; color: var(--s1); background: none; border: 1px solid var(--ring); border-radius: 6px; padding: 5px 12px; cursor: pointer; }
.fto2 .fb-note { font-size: 11.5px; color: var(--muted); max-width: 16em; line-height: 1.3; }
.fto2 .fb-sumrow { display: flex; align-items: center; gap: 6px 14px; flex-wrap: wrap; }
.fto2 .fb-info { font: inherit; font-size: 12.5px; border: 1px solid var(--ring); background: var(--surface); color: var(--ink-2); border-radius: 999px; padding: 3px 12px; cursor: pointer; }
.fto2 .fb-info[aria-expanded="true"] { border-color: var(--s1); color: var(--ink); }
.fto2 .fb-funnel { margin-top: 12px; border: 1px solid var(--ring); border-radius: 10px; padding: 14px 18px 12px; background: var(--surface); max-width: 920px; }
.fto2 .fb-funnel[hidden] { display: none; }
.fto2 .fb-funnel h3 { font-size: 14px; font-weight: 600; margin: 0 0 6px; }
.fto2 .fn-row { display: grid; grid-template-columns: minmax(0, 1fr) 64px 64px minmax(80px, 160px); gap: 12px; align-items: center; font-size: 13px; padding: 6px 0; border-top: 1px solid var(--grid); font-variant-numeric: tabular-nums; }
.fto2 .fn-row.hd { border-top: 0; font-size: 11.5px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; padding: 0 0 2px; }
.fto2 .fn-row .k small { display: block; color: var(--muted); font-size: 12px; margin-top: 1px; }
.fto2 .fn-row .out, .fto2 .fn-row .left { text-align: right; }
.fto2 .fn-row .out { color: var(--ink-2); }
.fto2 .fn-row .left { font-weight: 600; color: var(--ink); }
.fto2 .fn-row.off { color: var(--muted); }
.fto2 .fn-row.off .left { font-weight: 400; color: var(--muted); }
.fto2 .fn-row.end { border-top: 1px solid var(--ink); font-weight: 600; }
.fto2 .fn-bar { height: 8px; background: var(--track); border-radius: 4px; overflow: hidden; }
.fto2 .fn-bar i { display: block; height: 100%; background: var(--s1); border-radius: 4px; }
.fto2 .fn-note { font-size: 12.5px; color: var(--ink-2); margin: 8px 0 0; }
.fto2 .fb-sum { font-size: 13px; color: var(--ink-2); font-variant-numeric: tabular-nums; max-width: none; }
.fto2 .tabs { display: flex; gap: 2px; border-bottom: 1px solid var(--grid); overflow-x: auto; align-items: end; position: sticky; top: 0; z-index: 10; background: var(--page); }
.fto2 .tabs [role="tab"] { font: inherit; font-size: 15px; font-weight: 600; color: var(--ink-2); background: none; border: 0; border-bottom: 3px solid transparent; padding: 10px 14px 9px; cursor: pointer; white-space: nowrap; }
.fto2 .tabs [role="tab"][aria-selected="true"] { color: var(--ink); border-bottom-color: var(--ink); }
.fto2 .tabs [role="tab"]:hover { color: var(--ink); }
.fto2 .tabs .gap { width: 1px; align-self: stretch; margin: 10px 8px; background: var(--grid); flex: none; }
.fto2 .panel { display: grid; grid-template-columns: minmax(0, 1fr); gap: 18px; }
.fto2 .lead { display: grid; gap: 2px; }
.fto2 .lead h2 { font-family: var(--font-display); font-weight: 500; font-size: 26px; }
.fto2 .figs { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 200px), 1fr)); gap: 12px; }
.fto2 .fig { background: var(--surface); border: 1px solid var(--ring); border-radius: 8px; padding: 14px 16px; display: grid; gap: 2px; min-width: 0; align-content: start; }
.fto2 .fig { gap: 4px; }
.fto2 .fig > span { order: -1; font-size: 11.5px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; color: var(--muted); }
.fto2 .fig b { font-weight: 700; font-size: 28px; line-height: 1.1; font-variant-numeric: tabular-nums; }
.fto2 .fig b.word { font-size: 20px; line-height: 1.25; }
.fto2 .fig small { font-size: 12px; color: var(--muted); }
.fto2 .delta.up { color: var(--up); }
.fto2 .delta.down { color: var(--down); }
.fto2 .strip { display: flex; flex-wrap: wrap; gap: 6px 22px; font-size: 13.5px; color: var(--ink-2); font-variant-numeric: tabular-nums; background: var(--surface); border: 1px solid var(--ring); border-radius: 8px; padding: 10px 16px; }
.fto2 .strip b { color: var(--ink); font-weight: 600; }
.fto2 .section-head { display: flex; justify-content: space-between; align-items: end; gap: 12px; flex-wrap: wrap; }
.fto2 .section-head > div { display: grid; gap: 2px; min-width: 0; }
.fto2 .grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 340px), 1fr)); gap: 14px; }
.fto2 .card { background: var(--surface); border: 1px solid var(--ring); border-radius: 8px; padding: 14px 16px; display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; min-width: 0; align-content: start; }
.fto2 .card.wide { grid-column: 1 / -1; }
.fto2 .card-head { display: flex; justify-content: space-between; align-items: baseline; gap: 10px; flex-wrap: wrap; }
.fto2 .clear-one { font: inherit; font-size: 12px; color: var(--s1); background: none; border: 0; padding: 0; cursor: pointer; }
.fto2 .bars { display: grid; gap: 2px; }
.fto2 .bar { display: grid; grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 4.2em; align-items: center; gap: 10px; font: inherit; font-size: 13px; color: var(--ink); background: none; border: 0; border-radius: 4px; padding: 3px 4px; text-align: left; cursor: pointer; }
.fto2 .bars.money .bar { grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 6.4em; }
.fto2 .bars.pareto .bar { grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 4.2em 3.6em; }
.fto2 .bars.money.pareto .bar { grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 6.4em 3.6em; }
.fto2 .bars.longname .bar { grid-template-columns: minmax(0, 40em) minmax(0, 1fr) 4.2em; }
.fto2 .bars.x2 .bar { grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 6.4em 4.2em 4.2em; }
.fto2 .bars.x2.pareto .bar { grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 6.4em 4.2em 4.2em 3.6em; }
.fto2 .bars.x2.longname .bar { grid-template-columns: minmax(0, 34em) minmax(0, 1fr) 6.4em 4.2em 4.2em; }
.fto2 .bar .ext { text-align: right; font-variant-numeric: tabular-nums; color: var(--ink-2); }
.fto2 .barhead { display: grid; gap: 10px; padding: 0 4px; font-size: 11.5px; color: var(--muted); text-align: right; }
.fto2 .bars.x2 .barhead { grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 6.4em 4.2em 4.2em; }
.fto2 .bars.x2.pareto .barhead { grid-template-columns: minmax(0, 13em) minmax(0, 1fr) 6.4em 4.2em 4.2em 3.6em; }
.fto2 .bars.x2.longname .barhead { grid-template-columns: minmax(0, 34em) minmax(0, 1fr) 6.4em 4.2em 4.2em; }
.fto2 .card:not(.wide) .bars.x2 .bar, .fto2 .card:not(.wide) .bars.x2 .barhead { grid-template-columns: minmax(0, 1fr) 5.6em 3.6em 3.8em; row-gap: 3px; }
.fto2 .card:not(.wide) .bars.x2 .bar .track { grid-column: 1 / -1; grid-row: 2; height: 6px; }
.fto2 .card:not(.wide) .bars.x2 .barhead span:nth-child(2) { display: none; }
.fto2 .bar:hover { background: var(--track); }
.fto2 .bar .name { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fto2 .bar .track { position: relative; height: 13px; background: var(--track); border-radius: 2px; }
.fto2 .bar .fill { display: block; position: relative; overflow: hidden; height: 100%; background: var(--s1); border-radius: 0 4px 4px 0; }
.fto2 .bar .fill .cab { position: absolute; left: 0; top: 0; bottom: 0; background: var(--s2); }
.fto2 .bars.active .bar:not([aria-pressed="true"]) .fill .cab { opacity: .45; }
.fto2 .key i.c { background: var(--s2); }
.fto2 .bar.aside .fill { background: var(--dim); }
.fto2 .bar .tick { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--ref); border-radius: 1px; }
.fto2 .bar .val { text-align: right; font-variant-numeric: tabular-nums; color: var(--ink); }
.fto2 .bar .cum { text-align: right; font-variant-numeric: tabular-nums; color: var(--muted); font-size: 12px; }
.fto2 .bars.active .bar .fill { background: var(--dim); }
.fto2 .bars.active .bar[aria-pressed="true"] .fill { background: var(--s1); }
.fto2 .bar[aria-pressed="true"] { background: var(--s1-soft); }
.fto2 .bar[aria-pressed="true"] .name { font-weight: 600; }
.fto2 .bar.zero { color: var(--muted); }
.fto2 .sep { font-size: 11.5px; color: var(--muted); text-transform: uppercase; letter-spacing: .06em; padding: 8px 4px 2px; }
.fto2 .key { display: flex; gap: 14px; flex-wrap: wrap; font-size: 12.5px; color: var(--ink-2); }
.fto2 .key span { display: inline-flex; align-items: center; gap: 6px; }
.fto2 .key i { width: 10px; height: 10px; border-radius: 2px; display: inline-block; background: var(--s1); }
.fto2 .key i.t { width: 2px; height: 14px; background: var(--ref); }
.fto2 .cols-wrap { overflow-x: auto; }
.fto2 .cols { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(22px, 1fr); gap: 4px; align-items: end; height: 170px; min-width: 100%; }
.fto2 .col { font: inherit; display: grid; grid-template-rows: auto 1fr auto; justify-items: center; gap: 3px; height: 100%; background: none; border: 0; border-radius: 4px; padding: 2px 0; cursor: pointer; color: var(--ink); min-width: 0; }
.fto2 .col:hover { background: var(--track); }
.fto2 .col .v { font-size: 11px; color: var(--ink-2); font-variant-numeric: tabular-nums; }
.fto2 .col .stick { width: 72%; max-width: 24px; align-self: end; background: var(--s1); border-radius: 4px 4px 0 0; min-height: 1px; }
.fto2 .col.partial .stick { background: repeating-linear-gradient(135deg, var(--s1) 0 3px, transparent 3px 6px); border: 1px solid var(--s1); }
.fto2 .col .m { font-size: 10.5px; color: var(--ink-2); white-space: nowrap; }
.fto2 .cols.active .col .stick { background: var(--dim); border-color: var(--dim); }
.fto2 .cols.active .col[aria-pressed="true"] .stick { background: var(--s1); border-color: var(--s1); }
.fto2 .col[aria-pressed="true"] { background: var(--s1-soft); }
.fto2 .empty { font-size: 13px; color: var(--muted); padding: 6px 4px; }
.fto2 .chips { display: flex; gap: 8px; flex-wrap: wrap; align-items: center; min-height: 28px; }
.fto2 .chip { font: inherit; font-size: 12.5px; display: inline-flex; align-items: center; gap: 6px; padding: 3px 10px; border-radius: 999px; border: 1px solid var(--ring); background: var(--s1-soft); color: var(--ink); cursor: pointer; }
.fto2 .chip i { font-style: normal; color: var(--ink-2); }
.fto2 .chip.reset { background: transparent; color: var(--s1); }
.fto2 .chips .hint { font-size: 12.5px; color: var(--muted); }
.fto2 details.detail { background: var(--surface); border: 1px solid var(--ring); border-radius: 8px; }
.fto2 details.detail > summary { cursor: pointer; padding: 12px 16px; font-weight: 600; font-size: 14.5px; list-style-position: inside; }
.fto2 details.detail > summary .count { font-weight: 400; margin-left: 6px; }
.fto2 details.detail[open] > summary { border-bottom: 1px solid var(--grid); }
.fto2 details.detail .inner { padding: 12px 16px 16px; display: grid; gap: 12px; min-width: 0; }
.fto2 .toolbar { display: flex; gap: 12px; flex-wrap: wrap; align-items: center; justify-content: space-between; }
.fto2 input[type="search"] { font: inherit; font-size: 13.5px; padding: 6px 10px; border: 1px solid var(--ring); border-radius: 6px; background: var(--surface); color: var(--ink); width: min(100%, 320px); }
.fto2 .count { font-size: 13px; color: var(--ink-2); font-variant-numeric: tabular-nums; }
.fto2 .table-wrap { overflow-x: auto; border: 1px solid var(--ring); border-radius: 8px; background: var(--surface); }
.fto2 table { border-collapse: collapse; width: 100%; min-width: 900px; font-size: 13px; }
.fto2 th { text-align: left; font-weight: 600; font-size: 12px; color: var(--ink-2); padding: 9px 10px; border-bottom: 1px solid var(--grid); white-space: nowrap; background: var(--surface); }
.fto2 th.r, .fto2 td.r { text-align: right; }
.fto2 td { padding: 7px 10px; border-bottom: 1px solid var(--grid); vertical-align: top; }
.fto2 td.nc { font-family: var(--font-data); font-size: 12.5px; white-space: nowrap; }
.fto2 td.num { font-variant-numeric: tabular-nums; white-space: nowrap; }
.fto2 td.txt { min-width: 16em; color: var(--ink-2); }
.fto2 tr.open-row { cursor: pointer; }
.fto2 tr.open-row:hover td { background: var(--track); }
.fto2 tr.open-row[aria-expanded="true"] td { background: var(--s1-soft); border-bottom-color: transparent; }
.fto2 tr.more-row td { padding: 4px 10px 16px; }
.fto2 .more-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 360px), 1fr)); gap: 14px; }
.fto2 .more-grid h4, .fto2 .rcacard h4 { margin: 0 0 4px; font-size: 12px; font-weight: 600; letter-spacing: .04em; text-transform: uppercase; color: var(--ink-2); }
.fto2 .long { font-family: var(--font-data); font-size: 12px; white-space: pre-wrap; word-break: break-word; max-height: 280px; overflow: auto; background: var(--page); border: 1px solid var(--grid); border-radius: 6px; padding: 8px 10px; margin: 0; }
.fto2 dl.kv { display: grid; grid-template-columns: max-content minmax(0, 1fr); gap: 3px 12px; margin: 0; font-size: 12.5px; }
.fto2 dl.kv dt { color: var(--ink-2); }
.fto2 dl.kv dd { margin: 0; overflow-wrap: anywhere; }
.fto2 .tag { display: inline-block; font-size: 11.5px; padding: 1px 7px; border-radius: 999px; border: 1px solid var(--ring); color: var(--ink-2); white-space: nowrap; }
.fto2 .more { font: inherit; font-size: 13px; color: var(--s1); background: none; border: 1px solid var(--ring); border-radius: 6px; padding: 6px 12px; cursor: pointer; justify-self: start; }
.fto2 .weekbar { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }
.fto2 .weekbar button { font: inherit; font-size: 13px; padding: 5px 10px; border: 1px solid var(--ring); border-radius: 6px; background: var(--surface); color: var(--ink); cursor: pointer; }
