.fto2 .gcard { display: grid; grid-template-columns: minmax(0, 1fr); gap: 10px; align-content: start; padding: 30px 0 40px; border-top: 1px solid var(--ink); min-width: 0; }
.fto2 .ghead { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 14px; align-items: start; }
.fto2 .ghead > div { display: grid; gap: 6px; min-width: 0; }
.fto2 .gnum { font-family: var(--font-display); font-size: 46px; line-height: .9; color: var(--muted); font-variant-numeric: tabular-nums; }
.fto2 .ghead h3 { font-family: var(--font-display); font-weight: 400; font-size: 26px; line-height: 1.12; text-wrap: balance; }
.fto2 .keep { font: inherit; font-size: 12.5px; border: 1px solid var(--ring); background: var(--surface); color: var(--ink); border-radius: 999px; padding: 4px 12px; cursor: pointer; white-space: nowrap; }
.fto2 .keep[aria-pressed="true"] { background: var(--ink); color: var(--surface); border-color: var(--ink); font-weight: 600; }
.fto2 .feas { font-size: 12.5px; color: var(--ink-2); max-width: none; }
.fto2 .feas i { font-style: normal; font-weight: 700; margin-right: 4px; }
.fto2 .feas.ok i { color: var(--down); }
.fto2 .feas.part i { color: var(--c3); }
.fto2 .feas.need i { color: var(--up); }
.fto2 .gcard .vbody { min-height: 120px; }
.fto2 svg.viz .gk { fill: var(--surface); }
.fto2 svg.viz rect[fill="transparent"][data-tip]:hover { stroke: none; fill: var(--s1-soft); }
.fto2 footer { font-size: 12.5px; color: var(--muted); border-top: 1px solid var(--grid); padding-top: 14px; display: grid; gap: 4px; }
.fto2 footer p { max-width: none; }
@media (max-width: 560px) {
.fto2 .bars.x1 .bar, .fto2 .bars.x1.pareto .bar, .fto2 .bars.x1.longname .bar, .fto2 .bars.x1 .barhead, .fto2 .bars.x1.pareto .barhead, .fto2 .bars.x1.longname .barhead { grid-template-columns: minmax(0, 1fr) 3.6em 3.4em; row-gap: 3px; }
.fto2 .bars.x1 .bar .track { grid-column: 1 / -1; grid-row: 2; height: 6px; }
.fto2 .bars.x1 .cum, .fto2 .bars.x1 .barhead .cumh, .fto2 .bars.x1 .barhead span:nth-child(2) { display: none; }
.fto2 .bars.st .bar { grid-template-columns: minmax(0, 8em) minmax(0, 1fr) 5.6em; }
.fto2 .bar, .fto2 .bars.pareto .bar { grid-template-columns: minmax(0, 9em) minmax(0, 1fr) 3.6em; }
.fto2 .bars.pareto .bar .cum { display: none; }
.fto2 .bars.longname .bar { grid-template-columns: minmax(0, 1fr) 4em 3.4em; }
.fto2 .bars.x2 .bar, .fto2 .bars.x2.pareto .bar, .fto2 .bars.x2.longname .bar, .fto2 .bars.x2 .barhead, .fto2 .bars.x2.pareto .barhead, .fto2 .bars.x2.longname .barhead { grid-template-columns: minmax(0, 7em) minmax(0, 1fr) 4.6em 3em 3em; }
.fto2 .bars.x2 .cum, .fto2 .bars.x2 .barhead .cumh { display: none; }
.fto2 .card .bars.x2.money .bar, .fto2 .card .bars.x2.money .barhead { grid-template-columns: minmax(0, 1fr) 5em 3em 3.4em; row-gap: 3px; }
.fto2 .bars.x2 .bar .track { grid-column: 1 / -1; grid-row: 2; height: 6px; }
.fto2 .bars.x2 .barhead span:nth-child(2) { display: none; }
.fto2 .bars.money .bar, .fto2 .bars.money.pareto .bar { grid-template-columns: minmax(0, 8em) minmax(0, 1fr) 5.8em; }
.fto2 .level { grid-template-columns: minmax(0, 9em) minmax(0, 1fr) 6.4em; }
}
@media (prefers-reduced-motion: no-preference) {
.fto2 .fill, .fto2 .stick { transition: width .15s ease, height .15s ease; }
.fto2 .switch i::after { transition: left .15s ease; }
}
.fto2 .fto2-err { background: #fdecea; color: #8a1c12; border: 1px solid #f1b0a8; border-radius: 8px; padding: 10px 14px; font-size: 13px; margin: 12px 20px; }
.fto2 .fto2-wait { background: #eef4f1; color: #1d6b52; border: 1px solid #b9d5ca; border-radius: 8px; padding: 10px 14px; font-size: 13px; margin: 12px 20px; }
.fto2 .fto2-wait.warn { background: #fff5e6; color: #7a4a00; border-color: #f0c98a; }

